    function fetchPredicts(value) {
        fetch("https://www.google.com/complete/search?q=" + encodeURIComponent(value) + "&cp=" + encodeURIComponent(value) + "&client=gws-wiz&xssi=t&gs_pcrt=undefined&hl=" + encodeURIComponent(UGF_LANG_HL) + "&authuser=0&dpr=1", {
            method: "GET"
        }).then(response => {
            if (!response.ok) throw new Error("Prediction network response not ok");
            return response.text();
        }).then(data => {
            var cutString1 = data.split(")]}'");
            var used = cutString1[1];
            data = JSON.parse(used);
            var list = data[0];
            parsePredicts(list);
        }).catch(() => {});
    }
    function parsePredicts(list) {
        //API
        searchPredictsAPI = [];
        let itemNo = 0;
        list.forEach(itemRoot => {
            let text = itemRoot[0];
            searchPredictsAPI.push({searchPrediction: {
                content: text,
                itemNo: itemNo
            }});
            itemNo++;
        });
        createPredicts(searchPredictsAPI);
    }
