            let flags = "";
            el.querySelectorAll("[aria-label]").forEach(function(a) {
                const v = clean(a.getAttribute("aria-label"));
                if (v.indexOf(name) === 0 && v.length > name.length && v.length < name.length + 60) {
                    flags += " " + v.slice(name.length);
                }
            });
            const starBtn = el.querySelector("button[aria-label^='Remove from starred'], button[aria-label^='Add to starred']");
            const starred = starBtn ? /^Remove/.test(starBtn.getAttribute("aria-label")) : / Starred\b/.test(flags);
            const shared = / Shared\b/.test(flags) || /^Shared folder$/.test(type);
            const it = { id: id, el: el, name: name, type: type, kind: ugfDvKindOf(type || (/ folder\b/i.test(flags) ? "Folder" : "")), starred: starred, shared: shared,
                cols: {}, grid: el.getAttribute("role") === "gridcell" };
            // the other columns, by the head's names
            const table = el.closest("table");
            if (table) {
                const heads = {};
                table.querySelectorAll("thead th[data-column-field]").forEach(function(th) {
                    heads[th.getAttribute("data-column-field")] = clean(th.textContent);
                });
                el.querySelectorAll("td[data-column-field]").forEach(function(td) {
                    const h = heads[td.getAttribute("data-column-field")];
                    if (!h || td.getAttribute("data-column-field") === "6") {
                        return;
                    }
                    const lab = td.querySelector("[data-tooltip]");
                    it.cols[h] = clean(lab ? lab.getAttribute("data-tooltip") : td.textContent);
                });
            } else {
                const sub = el.querySelector(".uSZ2u, [class*='subtitle']");
                if (sub) {
                    it.cols.Location = clean(sub.textContent).replace(/^in /, "");
                }
            }
            const c = it.cols;
            it.owner = c.Owner || c["Shared by"] || "";
            it.modified = c["Last modified"] || c["Date modified"] || c["Last opened by me"] || c["Opened by me"] || c["Date shared"] || c["Trashed date"] || c["Date trashed"] ||
                (c["Reason suggested"] || "").replace(/^You (edited|modified|opened|created|uploaded)\s*•\s*/, "");
