        let clusterEnd = 0;
        const flush = function() {
            const cols = [];
            cluster.forEach(function(o) {
                let c = 0;
                while (cols[c] && cols[c] > o.s) {
                    c++;
                }
                cols[c] = o.e;
                o.col = c;
            });
            cluster.forEach(function(o) {
                o.cols = cols.length;
                out.push(o);
            });
            cluster = [];
        };
        evs.forEach(function(o) {
            if (cluster.length && o.s >= clusterEnd) {
                flush();
                clusterEnd = 0;
            }
            cluster.push(o);
            clusterEnd = Math.max(clusterEnd, o.e);
        });
