            let b = { lat: -90, lng: -180 };
            pts.forEach(function(p) {
                a = { lat: Math.min(a.lat, p.lat), lng: Math.min(a.lng, p.lng) };
                b = { lat: Math.max(b.lat, p.lat), lng: Math.max(b.lng, p.lng) };
            });
            map.fit([a, b], classic ? 40 : 80);
