            const a = ev.target.closest && ev.target.closest(".row");
            if (!a) {
                return;
            }
            const act = a.getAttribute("data-act");
            if (/^https?:/.test(act)) {
                return;   // an ordinary link
            }
            ev.preventDefault();
            const v = map.view();
            if (act.indexOf("type:") === 0) {
                const t = act.slice(5);
                map.setType(v.type === t ? "m" : t);
                paint();
                return;   // the menu stays open, so a second layer can be picked
            }
