            '#ugf-maps-panel .dsteps tr.st:hover td { background: #f5f8fe; }',
            '#ugf-maps-panel .dsteps .n { width: 22px; text-align: right; color: #333; }',
            '#ugf-maps-panel .dsteps .dd { white-space: nowrap; text-align: right; color: #666; }',
            '#ugf-maps-panel .note { color: #777; font-size: 11px; margin-top: 2px; }',
            '#ugf-maps-panel .dnote { color: #777; font-size: 11px; margin: 10px 0; line-height: 1.4; }',
            // directions, 2014 on
            '#ugf-maps-omni.dir #ugf-maps-form, #ugf-maps-omni.dir #ugf-maps-chips { display: none !important; }',
            '#ugf-maps-dirbox { background: #fff; box-shadow: 0 2px 4px rgba(0,0,0,.2); border-radius: 2px 2px 0 0; font: 13px Roboto, arial, sans-serif; }',
