            '#ugf-maps-dirbox .dmodes { display: flex; align-items: center; gap: 6px; margin: 0 0 8px 40px; }',
            '#ugf-maps-dirbox .dm { display: inline-flex; align-items: center; justify-content: center; width: 40px; height: 32px; border-radius: 16px; }',
            '#ugf-maps-dirbox .dm svg, #ugf-maps-dirbox .dclose svg, #ugf-maps-dirbox .dswap svg { display: block; fill: #757575; }',
            '#ugf-maps-dirbox .dm.on { background: #e8f0fe; } #ugf-maps-dirbox .dm.on svg { fill: #1a73e8; }',
            '#ugf-maps[era="m2015"] #ugf-maps-dirbox .dm svg, #ugf-maps[era="m2015"] #ugf-maps-dirbox .dclose svg, #ugf-maps[era="m2015"] #ugf-maps-dirbox .dswap svg { fill: rgba(255,255,255,.7); }',
            '#ugf-maps[era="m2015"] #ugf-maps-dirbox .dm.on { background: rgba(0,0,0,.15); } #ugf-maps[era="m2015"] #ugf-maps-dirbox .dm.on svg { fill: #fff; }',
            '#ugf-maps-dirbox .dclose { margin-left: auto; display: block; }',
            '#ugf-maps-dirbox .dflds { position: relative; padding-right: 36px; }',
            '#ugf-maps-dirbox .dfld { display: flex; align-items: center; height: 36px; }',
            '#ugf-maps-dirbox .dot { display: block; width: 8px; height: 8px; border-radius: 50%; border: 2px solid #757575; margin: 0 20px 0 14px; flex: 0 0 auto; }',
            '#ugf-maps-dirbox .dot.b { border-color: #db4437; background: #db4437; }',
            '#ugf-maps[era="m2015"] #ugf-maps-dirbox .dot { border-color: #fff; } #ugf-maps[era="m2015"] #ugf-maps-dirbox .dot.b { background: #fff; }',
            '#ugf-maps-dirbox input { flex: 1; min-width: 0; height: 32px; border: 0; border-bottom: 1px solid #e0e0e0; outline: none; background: transparent; font: 14px Roboto, arial, sans-serif; color: #222; padding: 0 4px; }',
            '#ugf-maps[era="m2015"] #ugf-maps-dirbox input { color: #fff; border-bottom-color: rgba(255,255,255,.5); }',
            '#ugf-maps[era="m2015"] #ugf-maps-dirbox input::placeholder { color: rgba(255,255,255,.7); }',
            '#ugf-maps-dirbox .dswap { position: absolute; right: 0; top: 24px; }',
