            '#ugf-maps-omni #ugf-maps-panel .rt.sel { border-left: 4px solid #4285f4; padding-left: 14px; }',
            '#ugf-maps-omni #ugf-maps-panel .rt .mi svg { display: block; fill: #757575; }',
            '#ugf-maps-omni #ugf-maps-panel .rt .rtx { flex: 1; min-width: 0; }',
            '#ugf-maps-omni #ugf-maps-panel .rt .l1 { display: flex; justify-content: space-between; }',
            '#ugf-maps-omni #ugf-maps-panel .rt .tm { font-size: 15px; color: #0f9d58; font-weight: 500; }',
            '#ugf-maps-omni #ugf-maps-panel .rt .ds { color: #757575; }',
